package app;

import app.category.CategoryRepository;
import app.customer.CustomerRepository;
import app.product.ProductRepository;
import app.producttag.ProductTagRepository;
import app.tag.TagRepository;
import java.util.function.Function;

/** What services depend on: a repository per table and a transaction. Services never commit: whoever holds the EntityManager opens and ends its transaction; transaction() only groups the code. */
public interface UnitOfWork {
    CustomerRepository customers();
    CategoryRepository categories();
    ProductRepository products();
    TagRepository tags();
    ProductTagRepository productTags();

    /** Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws. */
    <T> T transaction(Function<UnitOfWork, T> work);
}

