    public SqlProductRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public Optional<Product> findById(Long id) {
        return entityManager.createQuery("select e from Product e where e.id = :id", Product.class).setParameter("id", id)
                .getResultStream()
                .findFirst();
    }

    @Override
    public Page<Product> list(int offset, int limit) {
        List<Product> items = entityManager.createQuery("select e from Product e order by e.id", Product.class)
                .setFirstResult(offset)
                .setMaxResults(limit)
                .getResultList();
        long total = entityManager.createQuery("select count(e) from Product e", Long.class).getSingleResult();
        return new Page<>(items, total, offset, limit);
    }

    @Override
    public List<Product> listByCategoryId(Integer categoryId) {
        return entityManager.createQuery("select e from Product e where e.categoryId = :categoryId order by e.id", Product.class).setParameter("categoryId", categoryId).getResultList();
    }

    @Override
    public Product insert(Product entity) {
        try {
            entityManager.persist(entity);
            entityManager.flush();
            // Reads back what the database filled: the key, defaults
            entityManager.refresh(entity);
        } catch (PersistenceException error) {
            throw new ConflictException("Product", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public Product update(Product entity) {
        Product[] stored = new Product[1];
        try {
            stored[0] = entityManager.merge(entity);
            entityManager.flush();
        } catch (PersistenceException error) {
            throw new ConflictException("Product", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(Product entity) {
        try {
            entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
            entityManager.flush();
        } catch (PersistenceException error) {
            throw new ConflictException("Product", "the database refused the change: " + error.getMessage());
        }
    }
}

