package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.category.Category;
import app.category.CategoryChanges;
import app.category.CategoryService;
import app.common.Patch;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import jakarta.persistence.EntityManager;
import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "categories" table. */
class CategoryTest {
    private EntityManager entityManager;
    /** The repositories over the test database, opened empty for every test */
    private SqlUnitOfWork uow;

    @BeforeEach
    void open() {
        entityManager = TestDatabase.open();
        // The caller owns the transaction: the test opens it, and rolls it back at the end
        entityManager.getTransaction().begin();
        uow = new SqlUnitOfWork(entityManager);
    }

    @AfterEach
    void close() {
        if (entityManager.getTransaction().isActive()) entityManager.getTransaction().rollback();
        entityManager.close();
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Category stored = Factories.addCategory(uow, 1);
            uow.entityManager().clear();
            Category found = uow.categories().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
            assertTrue(uow.categories().findByName(stored.getName()).isPresent());
        }

        @Test
        void listsRowsByKey() {
            Factories.addCategory(uow, 1);
            Factories.addCategory(uow, 2);
            var page = uow.categories().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void isDeleted() {
            Category stored = Factories.addCategory(uow, 1);
            uow.categories().delete(stored);
            assertTrue(uow.categories().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class CategoryServiceTest {

        @Test
        void createsAValidRow() {
            CategoryService service = new CategoryService(uow);
            int n = 100;
            Category row = Factories.newCategory(1);
            var created = service.createCategory(row);
            var found = service.getCategory(created.getId());
            assertEquals(created.getId(), found.getId());
        }

        @Test
        void refusesAMissingValue() {
            CategoryService service = new CategoryService(uow);
            int n = 100;
            Category row = Factories.newCategory(1);
            row.setName(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createCategory(row));
            assertEquals(List.of("name"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesARepeatedUniqueValue() {
            CategoryService service = new CategoryService(uow);
            int n = 100;
            Category row = Factories.newCategory(1);
            var first = service.createCategory(row);
            Category again = Factories.newCategory(2);
            again.setName(first.getName());
            assertThrows(ConflictException.class, () -> service.createCategory(again));
        }

        @Test
        void keepsItsOwnUniqueValue() {
            CategoryService service = new CategoryService(uow);
            int n = 100;
            Category row = Factories.newCategory(1);
            var created = service.createCategory(row);
            service.updateCategory(created.getId(), new CategoryChanges(Patch.of(created.getName())));
        }

        @Test
        void saysWhenARowIsMissing() {
            CategoryService service = new CategoryService(uow);
            assertThrows(NotFoundException.class, () -> service.getCategory(999999));
        }

        @Test
        void deletesARow() {
            CategoryService service = new CategoryService(uow);
            int n = 100;
            Category row = Factories.newCategory(1);
